// Source fixtures: circuitpython-source/src/apps/Orion/modules/quantize.py and strum.py with
// core/note_array.py, core/utils.py and adafruit_ticks (2**29 ms wrap). Traces live in
// fixtures/t09i_source_traces.inc, generated by fixtures/t09i/gen_traces.py under python -I.
// Invariant tests below check grid alignment, wrap, stop and release safety against arithmetic
// models that do not reuse the implementation.
#include "modules/generated/module_counts_generated.hpp"
#include "modules/common/registry.hpp"
#include "modules/core/quantize/quantize_strum.hpp"
#include <cassert>
#include <cstdio>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <initializer_list>
#include <limits>

namespace {
using namespace orbit;

struct Pair {
  std::uint8_t pitch;
  std::uint8_t velocity;
};

std::uint32_t g_random_draws = 0;
std::uint32_t next_counter(void* ctx) { return ++*static_cast<std::uint32_t*>(ctx); }

bool equal(const char* a, const char* b) { return std::strcmp(a, b) == 0; }

// Replays one module through its descriptor, the same way the chain calls it.
struct Run {
  explicit Run(const ModuleDescriptor& descriptor) : d(descriptor) { d.construct(state); }
  ~Run() { d.destroy(state); }
  Run(const Run&) = delete;
  Run& operator=(const Run&) = delete;

  void set_int(std::uint8_t index, std::int32_t value) {
    std::uint8_t effects = 0;
    assert(d.set_param(state, index, ParamValue::integer(value), global, effects));
  }
  void set_float(std::uint8_t index, float value) {
    std::uint8_t effects = 0;
    assert(d.set_param(state, index, ParamValue::decimal(value), global, effects));
  }
  void set_global(std::uint8_t key, std::uint8_t scale) {
    global.key = key;
    global.scale = scale;
  }
  void stop() { d.reset(state, ResetReason::Stop); }

  NoteBatch process(std::uint32_t now, std::uint32_t tick, bool running, std::initializer_list<Pair> on,
                    std::initializer_list<std::uint8_t> off) {
    NoteBatch input{}, output{};
    for (const auto& p : on) assert(input.on.append({p.pitch, p.velocity, 0}) == PushResult::Added);
    for (const auto p : off) assert(input.off.append({p, 0, 0}) == PushResult::Added);
    TransportView view{};
    view.running = running;
    view.tick = tick;
    ProcessContext context{TimeSample{now, 0}, global, view, random};
    d.process(state, context, input, output);
    assert(!output.overflowed());
    assert(output.on.count <= kPolyphony && output.off.count <= kPolyphony);
    return output;
  }

  void step(std::uint32_t now, std::uint32_t tick, bool running, std::initializer_list<Pair> on,
            std::initializer_list<std::uint8_t> off, std::initializer_list<Pair> expected_on,
            std::initializer_list<std::uint8_t> expected_off) {
    const auto output = process(now, tick, running, on, off);
    if (!matches(output, expected_on, expected_off)) {
      std::fprintf(stderr, "MISMATCH now=%u tick=%u running=%d out_on=%u out_off=%u\n", now, tick,
                   running ? 1 : 0, static_cast<unsigned>(output.on.count), static_cast<unsigned>(output.off.count));
      for (std::uint16_t i = 0; i < output.on.count; ++i) std::fprintf(stderr, " on %u/%u", output.on.items[i].pitch, output.on.items[i].velocity);
      for (std::uint16_t i = 0; i < output.off.count; ++i) std::fprintf(stderr, " off %u", output.off.items[i].pitch);
      std::fprintf(stderr, "\n");
    }
    assert(matches(output, expected_on, expected_off));
  }

  // A documented deviation: the C++ result must match cpp_*, and the source result must not.
  void step_dev(std::uint32_t now, std::uint32_t tick, bool running, std::initializer_list<Pair> on,
                std::initializer_list<std::uint8_t> off, std::initializer_list<Pair> source_on,
                std::initializer_list<std::uint8_t> source_off, std::initializer_list<Pair> cpp_on,
                std::initializer_list<std::uint8_t> cpp_off) {
    const auto output = process(now, tick, running, on, off);
    assert(matches(output, cpp_on, cpp_off));
    assert(!matches(output, source_on, source_off));
  }

  static bool matches(const NoteBatch& output, std::initializer_list<Pair> on, std::initializer_list<std::uint8_t> off) {
    if (static_cast<std::size_t>(output.on.count) != on.size()) return false;
    if (static_cast<std::size_t>(output.off.count) != off.size()) return false;
    std::size_t i = 0;
    for (const auto& p : on) {
      if (output.on.items[i].pitch != p.pitch || output.on.items[i].velocity != p.velocity) return false;
      ++i;
    }
    i = 0;
    for (const auto p : off) {
      if (output.off.items[i++].pitch != p) return false;
    }
    return true;
  }

  const ModuleDescriptor& d;
  ModuleState state{};
  GlobalState global{};
  RandomSource random{&g_random_draws, next_counter};
};

using TraceFn = void (*)(Run&);
struct NamedTrace {
  const char* name;
  TraceFn run;
};

#include "fixtures/t09i_source_traces.inc"

const QuantizeModuleState& quantize_state(const Run& r) { return r.state.storage.quantize; }
const StrumModuleState& strum_state(const Run& r) { return r.state.storage.strum; }

// Source rate table (quantize.py RATE_MIDI_TICKS): an independent copy for the arithmetic models.
constexpr std::uint32_t kRateTicks[13] = {96, 64, 48, 32, 24, 16, 12, 8, 6, 4, 3, 2, 1};

void run_all_traces(const ModuleDescriptor& descriptor, const NamedTrace* traces, std::size_t count) {
  for (std::size_t i = 0; i < count; ++i) {
    Run r(descriptor);
    traces[i].run(r);
  }
}

void test_source_traces() {
  run_all_traces(quantize_module_descriptor(), kQuantizeTraces, sizeof(kQuantizeTraces) / sizeof(kQuantizeTraces[0]));
  run_all_traces(strum_module_descriptor(), kStrumTraces, sizeof(kStrumTraces) / sizeof(kStrumTraces[0]));
}

void test_descriptors() {
  const auto* quantize = find_module("quantize");
  const auto* strum = find_module("strum");
  assert(quantize && quantize == &quantize_module_descriptor() && module_at(12) == quantize);
  assert(strum && strum == &strum_module_descriptor() && module_at(15) == strum);
  assert(module_count() == orbit::kGeneratedProcessorCount && !find_module("phraser"));

  // quantize.py: one main parameter, RATE, default 8, 1/64..1/1 index range 0..12.
  const auto& q = *quantize;
  assert(q.version == 1 && q.param_count == 1);
  assert(equal(q.params[0].name, "rate") && equal(q.params[0].display_label, "RATE"));
  assert(q.params[0].default_value.value.integer == 8 && q.params[0].minimum.value.integer == 0 &&
         q.params[0].maximum.value.integer == 12 && q.params[0].step.value.integer == 1);
  assert(q.params[0].flags == ParamPersist);

  // strum.py: AMT, ORDR, TILT, CNT, ARTC in that order.
  const auto& s = *strum;
  assert(s.version == 1 && s.param_count == 5);
  assert(equal(s.params[0].name, "amount") && equal(s.params[0].display_label, "AMT"));
  assert(equal(s.params[1].name, "order") && equal(s.params[1].display_label, "ORDR"));
  assert(equal(s.params[2].name, "tilt") && equal(s.params[2].display_label, "TILT"));
  assert(equal(s.params[3].name, "tilt_note_count") && equal(s.params[3].display_label, "CNT"));
  assert(equal(s.params[4].name, "articulate") && equal(s.params[4].display_label, "ARTC"));
  assert(s.params[0].default_value.value.integer == 30 && s.params[0].minimum.value.integer == 0 &&
         s.params[0].maximum.value.integer == 1000000);
  assert(s.params[1].default_value.value.integer == 0 && s.params[1].maximum.value.integer == 4 &&
         s.params[1].option_count == 5);
  assert(s.params[2].default_value.value.decimal == 0.0f && s.params[2].minimum.value.decimal == -1.0f &&
         s.params[2].maximum.value.decimal == 1.0f);
  assert(s.params[3].default_value.value.integer == 3 && s.params[3].minimum.value.integer == 1 &&
         s.params[3].maximum.value.integer == 12);
  assert(s.params[4].default_value.value.integer == 0 && s.params[4].maximum.value.integer == 8 &&
         s.params[4].option_count == 9);
  assert(equal(s.params[1].options[3], "UPDWN") && equal(s.params[4].options[5], "HUMN"));

  // Ranges and types are validated; rejected values leave state unchanged.
  Run rq(q);
  std::uint8_t effects = 0xff;
  assert(rq.d.set_param(rq.state, 0, ParamValue::integer(13), rq.global, effects) == false);
  assert(rq.d.set_param(rq.state, 0, ParamValue::decimal(3.0f), rq.global, effects) == false);
  assert(rq.d.set_param(rq.state, 0, ParamValue::integer(0), rq.global, effects) && effects == EffectNone);
  assert(quantize_state(rq).rate_index == 0);

  Run rs(s);
  assert(rs.d.set_param(rs.state, 1, ParamValue::integer(5), rs.global, effects) == false);  // minmax admits 5; reject
  assert(rs.d.set_param(rs.state, 4, ParamValue::integer(9), rs.global, effects) == false);
  assert(rs.d.set_param(rs.state, 0, ParamValue::integer(-1), rs.global, effects) == false);
  assert(rs.d.set_param(rs.state, 2, ParamValue::decimal(1.5f), rs.global, effects) == false);
  assert(rs.d.set_param(rs.state, 2, ParamValue::integer(0), rs.global, effects) == false);
  assert(rs.d.set_param(rs.state, 3, ParamValue::integer(0), rs.global, effects) == false);
  assert(rs.d.set_param(rs.state, 0, ParamValue::integer(1000001), rs.global, effects) == false);
  assert(strum_state(rs).amount == 30 && strum_state(rs).order == 0 && strum_state(rs).tilt == 0.0f);
  assert(rs.d.set_param(rs.state, 2, ParamValue::decimal(-1.0f), rs.global, effects) && effects == EffectNone);
  assert(strum_state(rs).tilt == -1.0f);
}

// Tick alignment: a note-on at tick T is promoted at the first grid tick strictly after T, for
// every rate and phase, from a fresh state.
void test_grid_alignment() {
  for (std::uint8_t index = 0; index < 13; ++index) {
    const std::uint32_t rate = kRateTicks[index];
    for (std::uint32_t start = 0; start <= 2 * rate + 1; ++start) {
      Run r(quantize_module_descriptor());
      r.set_int(0, index);
      auto first = r.process(0, start, true, {{60, 100}}, {});
      assert(first.on.count == 0);
      const std::uint32_t expected = (start / rate + 1) * rate;
      std::uint32_t promoted_at = 0;
      for (std::uint32_t tick = start + 1; tick <= expected + 1; ++tick) {
        const auto out = r.process(0, tick, true, {}, {});
        if (out.on.count > 0) {
          promoted_at = tick;
          assert(out.on.count == 1 && out.on.items[0].pitch == 60 && out.on.items[0].velocity == 100);
          break;
        }
      }
      assert(promoted_at == expected);
    }
  }
}

// Wrap: the grid continues across the uint32 tick wrap as if the tick were unbounded.
void test_tick_wrap_grid() {
  for (std::uint8_t index : {std::uint8_t{0}, std::uint8_t{7}, std::uint8_t{12}}) {
    const std::uint64_t rate = kRateTicks[index];
    const std::uint64_t absolute_start = 0xFFFFFFF0ULL;
    Run r(quantize_module_descriptor());
    r.set_int(0, index);
    const std::uint64_t promote_at = (absolute_start / rate + 1) * rate;
    r.process(0, static_cast<std::uint32_t>(absolute_start), true, {{64, 90}}, {});
    bool promoted = false;
    for (std::uint64_t absolute = absolute_start + 1; absolute <= promote_at + 1; ++absolute) {
      const auto out = r.process(0, static_cast<std::uint32_t>(absolute), true, {}, {});
      if (out.on.count > 0) {
        assert(absolute == promote_at);
        assert(out.on.items[0].pitch == 64 && out.on.items[0].velocity == 90);
        promoted = true;
        break;
      }
    }
    assert(promoted);
  }
}

// Backwards transport restarts (tick decreases) keep the absolute grid, as the source does.
void test_backwards_tick_grid() {
  Run r(quantize_module_descriptor());
  r.set_int(0, 7);  // 8 ticks
  r.process(0, 100, true, {{60, 100}}, {});  // target 104
  assert(r.process(0, 50, true, {}, {}).on.count == 0);
  assert(r.process(0, 103, true, {}, {}).on.count == 0);
  const auto out = r.process(0, 104, true, {}, {});
  assert(out.on.count == 1 && out.on.items[0].pitch == 60);
}

// Stop clears pending and held state; later releases for cleared notes emit nothing.
void test_quantize_stop() {
  Run r(quantize_module_descriptor());
  r.set_int(0, 12);  // 1 tick
  r.process(0, 0, true, {{60, 100}, {64, 90}}, {});
  r.process(0, 1, true, {}, {});  // promotes both
  r.process(0, 2, true, {}, {60});  // schedules release of 60
  r.stop();
  assert(quantize_state(r).pending_count == 0 && quantize_state(r).scheduled_count == 0 &&
         quantize_state(r).held.count == 0);
  assert(r.process(0, 3, true, {}, {}).off.count == 0);
  assert(r.process(0, 4, true, {}, {64}).off.count == 0);
  assert(r.process(0, 5, true, {}, {}).on.count == 0);
}

// Stop on strum clears the register and outputs only; the strum schedule and count persist, and
// the next pass with an empty register ends the strum (source Strum.stop behavior).
void test_strum_stop() {
  Run r(strum_module_descriptor());
  r.set_int(0, 0);  // AMT 0
  r.step(0, 0, true, {{60, 100}, {64, 90}}, {}, {}, {});
  r.stop();
  assert(strum_state(r).register_notes.count == 0);
  assert(strum_state(r).strum_active && strum_state(r).strum_count == 0);
  r.step(10, 0, true, {}, {}, {}, {});
  assert(!strum_state(r).strum_active && strum_state(r).strum_count == 1);
  assert(strum_state(r).register_notes.count == 0);
}

// Strum deadlines fire strictly after the scheduled time (ticks_diff(next, now) < 0), including
// across the uint32 millisecond wrap.
void test_strum_strict_deadline() {
  for (std::uint32_t start : {std::uint32_t{1000}, std::uint32_t{0xFFFFFFF8}, std::uint32_t{0xFFFFFFFF}}) {
    Run r(strum_module_descriptor());
    r.set_int(0, 0);
    r.step(start, 0, true, {{60, 100}}, {}, {}, {});
    r.step(start, 0, true, {}, {}, {}, {});  // equal time: not yet due
    r.step(start + 1, 0, true, {}, {}, {{60, 100}}, {});
    assert(strum_state(r).register_notes.count == 0);
  }
}

// Deviation (strum S1): the same pitch in the on and off lists of one batch. The source keeps the
// register entry, forwards the off, and later emits a note-on with no release (a stuck note). The
// C++ removes the entry; the note-on is therefore not emitted and the other chord tone sounds.
void test_strum_same_batch_on_off_deviation() {
  Run r(strum_module_descriptor());
  r.set_int(0, 0);  // AMT 0: one emission per pass
  const auto first = r.process(0, 0, true, {{60, 100}, {64, 90}}, {60});
  assert(first.on.count == 0);
  assert(first.off.count == 1 && first.off.items[0].pitch == 60);
  const auto second = r.process(10, 1, true, {}, {});
  assert(second.on.count == 1 && second.on.items[0].pitch == 64 && second.on.items[0].velocity == 90);
  assert(second.off.count == 0);
  assert(r.process(20, 2, true, {}, {}).on.count == 0);
  assert(strum_state(r).register_notes.count == 0);
}

// Release safety for quantize: random presses and releases, then a drain. Every emitted note-on
// has a release emitted at or after it, and no pass overflows the batch.
void test_quantize_no_stuck_notes() {
  struct Lcg {
    std::uint32_t s;
    std::uint32_t next() { s = s * 1664525U + 1013904223U; return s >> 8; }
    std::uint32_t range(std::uint32_t n) { return next() % n; }
  };
  for (std::uint32_t seed = 1; seed <= 32; ++seed) {
    Lcg rng{seed * 7919U + 3U};
    Run r(quantize_module_descriptor());
    r.set_int(0, static_cast<std::int32_t>(rng.range(13)));
    bool pressed[128]{};
    std::uint32_t emitted_on[128]{};
    std::uint32_t emitted_off[128]{};
    std::uint32_t now = 0;
    std::uint32_t tick = 0;
    for (int i = 0; i < 2500; ++i) {
      now += 1 + rng.range(40);
      tick += rng.range(3);
      if (rng.range(60) == 0) tick = rng.range(20);  // Backwards restart.
      NoteBatch input{};
      bool touched[128]{};
      const std::uint32_t actions = rng.range(4);
      for (std::uint32_t k = 0; k < actions; ++k) {
        const auto pitch = static_cast<std::uint8_t>(48 + rng.range(24));
        if (touched[pitch]) continue;
        touched[pitch] = true;
        if (pressed[pitch]) {
          assert(input.off.append({pitch, 0, 0}) == PushResult::Added);
          pressed[pitch] = false;
        } else {
          assert(input.on.append({pitch, 100, 0}) == PushResult::Added);
          pressed[pitch] = true;
        }
      }
      NoteBatch output{};
      TransportView view{};
      view.running = true;
      view.tick = tick;
      ProcessContext context{TimeSample{now, 0}, r.global, view, r.random};
      r.d.process(r.state, context, input, output);
      assert(!output.overflowed());
      for (std::uint16_t k = 0; k < output.on.count; ++k) ++emitted_on[output.on.items[k].pitch];
      for (std::uint16_t k = 0; k < output.off.count; ++k) ++emitted_off[output.off.items[k].pitch];
    }
    // Release every key still held, then drain until nothing is pending or scheduled.
    for (std::uint8_t pitch = 48; pitch < 72; ++pitch) {
      if (!pressed[pitch]) continue;
      const auto output = r.process(now, tick, true, {}, {pitch});
      for (std::uint16_t k = 0; k < output.on.count; ++k) ++emitted_on[output.on.items[k].pitch];
      for (std::uint16_t k = 0; k < output.off.count; ++k) ++emitted_off[output.off.items[k].pitch];
    }
    for (int i = 0; i < 4000 && (quantize_state(r).pending_count > 0 || quantize_state(r).scheduled_count > 0); ++i) {
      ++tick;
      const auto output = r.process(now, tick, true, {}, {});
      for (std::uint16_t k = 0; k < output.on.count; ++k) ++emitted_on[output.on.items[k].pitch];
      for (std::uint16_t k = 0; k < output.off.count; ++k) ++emitted_off[output.off.items[k].pitch];
    }
    assert(quantize_state(r).pending_count == 0 && quantize_state(r).scheduled_count == 0);
    for (std::size_t pitch = 0; pitch < 128; ++pitch) assert(emitted_on[pitch] <= emitted_off[pitch]);
  }
}

// Strum release safety: a note-on is emitted only while its pitch is held, at most once per press,
// and the register is empty after the drain.
void test_strum_press_model() {
  struct Lcg {
    std::uint32_t s;
    std::uint32_t next() { s = s * 1664525U + 1013904223U; return s >> 8; }
    std::uint32_t range(std::uint32_t n) { return next() % n; }
  };
  for (std::uint32_t seed = 1; seed <= 32; ++seed) {
    Lcg rng{seed * 104729U + 11U};
    Run r(strum_module_descriptor());
    r.set_int(0, static_cast<std::int32_t>(rng.range(301)));
    r.set_int(1, static_cast<std::int32_t>(rng.range(5)));
    r.set_int(3, static_cast<std::int32_t>(1 + rng.range(12)));
    r.set_int(4, static_cast<std::int32_t>(rng.range(9)));
    r.set_float(2, static_cast<float>(static_cast<int>(rng.range(41)) - 20) / 20.0f);
    bool pressed[128]{};
    std::uint32_t since_press[128]{};
    std::uint32_t now = 0;
    auto emit = [&](const NoteBatch& output) {
      for (std::uint16_t k = 0; k < output.on.count; ++k) {
        const auto pitch = output.on.items[k].pitch;
        assert(pressed[pitch]);
        assert(since_press[pitch] == 0);
        since_press[pitch] = 1;
        assert(output.on.items[k].velocity <= 127);
      }
    };
    for (int i = 0; i < 1500; ++i) {
      now += 1 + rng.range(30);
      NoteBatch input{};
      bool touched[128]{};
      const std::uint32_t actions = rng.range(4);
      for (std::uint32_t k = 0; k < actions; ++k) {
        const auto pitch = static_cast<std::uint8_t>(48 + rng.range(24));
        if (touched[pitch]) continue;
        touched[pitch] = true;
        if (pressed[pitch]) {
          assert(input.off.append({pitch, 0, 0}) == PushResult::Added);
          pressed[pitch] = false;
        } else {
          assert(input.on.append({pitch, 100, 0}) == PushResult::Added);
          pressed[pitch] = true;
          since_press[pitch] = 0;
        }
      }
      NoteBatch output{};
      TransportView view{};
      view.running = true;
      ProcessContext context{TimeSample{now, 0}, r.global, view, r.random};
      r.d.process(r.state, context, input, output);
      assert(!output.overflowed());
      emit(output);
    }
    for (std::uint8_t pitch = 48; pitch < 72; ++pitch) {
      if (!pressed[pitch]) continue;
      NoteBatch output = r.process(now, 0, true, {}, {pitch});
      pressed[pitch] = false;
      emit(output);
    }
    for (int i = 0; i < 4000 && strum_state(r).register_notes.count > 0; ++i) {
      now += 1000;
      NoteBatch output = r.process(now, 0, true, {}, {});
      emit(output);
    }
    assert(strum_state(r).register_notes.count == 0);
  }
}

// Reports the union sizes for the report (the budget check is the shared ModuleState size).
void test_state_sizes() {
  std::fprintf(stderr, "t09i sizes: ModuleState=%zu QuantizeModuleState=%zu StrumModuleState=%zu\n",
               sizeof(ModuleState), sizeof(QuantizeModuleState), sizeof(StrumModuleState));
  assert(sizeof(ModuleState) >= sizeof(QuantizeModuleState) && sizeof(ModuleState) >= sizeof(StrumModuleState));
}

}  // namespace

int main() {
  test_descriptors();
  test_source_traces();
  test_grid_alignment();
  test_tick_wrap_grid();
  test_backwards_tick_grid();
  test_quantize_stop();
  test_strum_stop();
  test_strum_strict_deadline();
  test_strum_same_batch_on_off_deviation();
  test_quantize_no_stuck_notes();
  test_strum_press_model();
  test_state_sizes();
  std::puts("t09i_quantize_strum: all checks passed");
  return 0;
}
